<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { RouterLink,useRoute,useRouter } from 'vue-router'
import { api,ApiError,date,money,status,type Customer,type Order,type Page } from '../api'
import { confirmedOrder,confirmedOwner,reserveCommand,reservationBusy,reservationPending } from '../reservations'
import ReservationPending from '../components/ReservationPending.vue'
import { uuidPattern } from '../customerCommands'
const route=useRoute(),router=useRouter(),customer=ref<Customer|null>(null),data=ref<Page<Order>|null>(null),page=ref(1),error=ref(''),loading=ref(false),clock=ref(Date.now()),scenarios=ref<Record<string,string>>({}),focusedOrder=ref<Order|null>(null)
let disposed=false
const orders=computed(()=>{const items=data.value?.items.slice()||[],last=confirmedOwner.value===customer.value?.id?confirmedOrder.value:null;if(page.value===1&&focusedOrder.value&&!items.some(o=>o.id===focusedOrder.value!.id))items.unshift(focusedOrder.value);if(page.value===1&&last){const i=items.findIndex(o=>o.id===last.id);if(i>=0)items[i]=last;else items.unshift(last)}return items})
async function load(silent=false){if(loading.value||disposed)return;loading.value=true;if(!silent)error.value='';try{
 const me=await api<Customer>('/customer/auth/me');if(disposed)return;if(me.id!==customer.value?.id){data.value=null;focusedOrder.value=null}customer.value=me
 const headers={'X-Expected-Customer-ID':me.id},result=await api<Page<Order>>('/customer/orders?page='+page.value,{headers});if(disposed)return;data.value=result
 if(page.value===1&&typeof route.query.orderId==='string'&&uuidPattern.test(route.query.orderId)){const focus=await api<Order>('/customer/orders/'+route.query.orderId,{headers});if(disposed)return;if(focus.id!==route.query.orderId)throw new ApiError(0,'訂單回覆不完整，請重新核對');focusedOrder.value=focus}
 const last=confirmedOwner.value===customer.value?.id?confirmedOrder.value:null;if(last){const fresh=data.value.items.find(o=>o.id===last.id)||focusedOrder.value;if(fresh?.id===last.id&&fresh.version>=last.version)confirmedOrder.value=fresh}
 }catch(e){if(disposed)return;if(e instanceof ApiError&&e.status===401){customer.value=null;data.value=null;focusedOrder.value=null;await router.replace({path:'/account/login',query:{returnTo:'/account/orders'}})}else error.value=(e as Error).message}finally{if(!disposed)loading.value=false}}
async function cancel(order:Order){if(!customer.value)return;error.value='';try{await reserveCommand(customer.value,'/customer/orders/'+order.id+'/cancel',{expectedVersion:order.version});await load()}catch(e){error.value=(e as Error).message}}
async function payment(order:Order){if(!customer.value)return;error.value='';try{await reserveCommand(customer.value,'/customer/orders/'+order.id+'/payments',{expectedVersion:order.version,expectedTotalTwd:order.totalTwd,scenario:scenarios.value[order.id]||'SUCCESS'});await load()}catch(e){error.value=(e as Error).message}}
async function reconcile(order:Order){if(!customer.value||!order.payment)return;error.value='';try{await reserveCommand(customer.value,'/customer/orders/'+order.id+'/payments/'+order.payment.id+'/reconcile',{});await load()}catch(e){error.value=(e as Error).message}}
const blocked=computed(()=>loading.value||reservationBusy.value||!!reservationPending.value)
function reviewReason(reason:string|null){return ({LATE_SUCCESS:'結果晚於取消或截止，保票不會恢復。',AMOUNT_MISMATCH:'金額或貨幣不符，等待人工核對。',EXTRA_EVENT:'收到額外付款事件，等待人工核對。'}[reason||'']||'請核對付款紀錄。')}
async function move(step:number){page.value+=step;data.value=null;await load()}
function remaining(o:Order){const seconds=Math.max(0,Math.ceil((Date.parse(o.expiresAt)-clock.value)/1000));return seconds?Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0'):'等待伺服器更新'}
let timer:ReturnType<typeof setInterval>,poll:ReturnType<typeof setInterval>
onMounted(()=>{void load();timer=setInterval(()=>clock.value=Date.now(),1000);poll=setInterval(()=>{if(!reservationBusy.value)void load(true)},10000)})
onUnmounted(()=>{disposed=true;clearInterval(timer);clearInterval(poll)})
</script>
<template><section class="content detail-page"><RouterLink to="/account" class="back-link">← 會員空間</RouterLink><div class="event-title"><div class="eyebrow">MY RESERVATIONS</div><h1>你的保票訂單。</h1><p class="muted">僅提供免費模擬付款，不輸入卡號、不會真收款。倒數僅供參考，期限與票額以伺服器為準。</p></div><ReservationPending :customer="customer" @confirmed="load()"/><p v-if="error" class="notice error" role="alert">{{error}}</p><button :disabled="loading||reservationBusy" @click="load()">重新讀取訂單</button><p v-if="loading" role="status">讀取中…</p><div v-if="!orders.length&&!loading&&!error" class="empty"><h2>還沒有保票訂單。</h2><RouterLink to="/">探索活動 ↗</RouterLink></div><article v-for="o in orders" :key="o.id" :id="'order-'+o.id" class="panel order-card"><div class="section-heading"><div><h2>{{o.eventTitle}}</h2><p>{{o.sessionName}} · {{date(o.startsAt)}}</p></div><span class="badge">{{status(o.status)}}</span></div><p>{{o.ticketName}} · {{o.quantity}} 張 · {{money(o.totalTwd)}}</p><p class="muted order-id">訂單 {{o.id}}</p><p>保留期限 {{date(o.expiresAt)}}</p><p v-if="o.status==='PENDING_PAYMENT'" class="reservation-clock">剩餘 {{remaining(o)}}</p><button v-if="o.status==='PENDING_PAYMENT'" :disabled="loading||reservationBusy||!!reservationPending" @click="cancel(o)">取消保票</button><p v-else-if="o.status==='PAID'" class="muted">模擬付款已轉為已售票額；可查看或領取電子票券，退款流程待補。</p><p v-else class="muted">保留已釋放，這筆訂單不會重新保票。</p>
<RouterLink v-if="o.status==='PAID'" :to="`/account/orders/${o.id}/tickets`" class="button-link">查看電子票券 ↗</RouterLink>
<div v-if="o.payment" class="payment-section"><h3>模擬付款 · {{status(o.payment.status)}}</h3><p class="muted order-id">付款 {{o.payment.id}} · {{money(o.payment.amountTwd)}}</p><p v-if="o.payment.status==='PENDING'">付款指令已保存，結果尚待核對。只核對原付款，不會建立第二次付款。</p><p v-if="o.payment.status==='REVIEW'" class="notice warning">{{reviewReason(o.payment.reason)}} 此展示沒有真扣款；請勿新增付款或自行補回票額。</p><p v-if="o.payment.status==='DECLINED'" class="muted">模擬付款被拒絕，可取消保票或等待到期。本階段不提供第二次付款。</p><button v-if="o.payment.status==='PENDING'" :disabled="blocked" @click="reconcile(o)">核對原模擬付款</button></div>
<form v-else-if="o.status==='PENDING_PAYMENT'&&o.mockPaymentsEnabled" class="payment-section" @submit.prevent="payment(o)"><fieldset :disabled="blocked"><label>模擬付款情境<select :value="scenarios[o.id]||'SUCCESS'" @change="scenarios[o.id]=($event.target as HTMLSelectElement).value"><option value="SUCCESS">模擬成功（手動核對後確認）</option><option value="DECLINED">模擬拒絕</option></select></label><p class="muted">先保存付款，再核對結果；取消／到期後的成功會進入待人工核對，不復活保票。</p><button class="primary">建立模擬付款</button></fieldset></form><p v-else-if="!o.payment&&o.status==='PENDING_PAYMENT'" class="muted">模擬付款尚未開放。</p></article><div v-if="data" class="pagination"><button :disabled="page===1||loading" @click="move(-1)">上一頁</button><span>第 {{page}} 頁 · {{data.total}} 筆</span><button :disabled="page*data.size>=data.total||loading" @click="move(1)">下一頁</button></div></section></template>
